using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
public static class JewelUiInspect {
 public static string Run() {
 var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
 EditorSceneManager.SaveScene(scene,System.IO.Path.GetFullPath(".codex-jewel-ui-work/scene-before.unity"),true);
 var rows=UnityEngine.Object.FindObjectsByType<PinkJewelIconRow>(FindObjectsInactive.Include);
 return "dirty="+scene.isDirty+"\n"+string.Join("\n",rows.Select(r=>r.name+" parent="+r.transform.parent.name+" rect="+((RectTransform)r.transform).rect+" anchor="+((RectTransform)r.transform).anchorMin+" position="+((RectTransform)r.transform).anchoredPosition+" data="+EditorJsonUtility.ToJson(r)));
 }
}
